using System.Linq;
using LastRail.Battle;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.UI;
public class CombatExteriorQualityTests {
 static CombatSceneDriver Driver(){var p=new Ce03RailPreparation(CombatRailPreparationTests.Golden(),"a",1);var d=new CombatSceneDriver(()=>p.CreateModel(1),()=>null,(s,r)=>r+1,()=>true);d.Open();return d;}
 static GameObject View(CombatSceneDriver d){var g=new GameObject("exterior-test",typeof(RectTransform),typeof(Canvas));g.AddComponent<ApprovedCombatView>().Bind(d,LastRail.Resources.PreparedContent.Load<CombatPresentationAssets>("CombatPresentation/approved"));return g;}
 [Test] public void HiddenApertureBorderCannotFocusAnInvisibleActor(){var g=View(Driver());try{var viewport=(RectTransform)g.transform.Find("ApprovedBattle/ExteriorViewport");var filter=viewport.GetComponent<Graphic>() as ICanvasRaycastFilter;Assert.NotNull(filter,"Stencil drawing alone does not filter pointer hits");var r=viewport.rect;Vector2 Screen(float x,float y)=>RectTransformUtility.WorldToScreenPoint(null,viewport.TransformPoint(new Vector2(r.xMin+x,r.yMax-y)));Assert.IsFalse(filter.IsRaycastLocationValid(Screen(2,2),null));Assert.IsFalse(filter.IsRaycastLocationValid(Screen(18,16),null));Assert.IsTrue(filter.IsRaycastLocationValid(Screen(360,130),null));}finally{Object.DestroyImmediate(g);}}
 [Test] public void EveryExteriorLayerSharesChamferedStencilWithoutMovingViewport(){var g=View(Driver());try{var viewport=(RectTransform)g.transform.Find("ApprovedBattle/ExteriorViewport");Assert.AreEqual(new Vector2(0,-66),viewport.anchoredPosition);Assert.AreEqual(new Vector2(720,273),viewport.sizeDelta);var mask=viewport.GetComponent<Mask>();Assert.NotNull(mask,"RectMask alone leaks through transparent bezel corners");Assert.IsFalse(mask.showMaskGraphic);var graphic=viewport.GetComponent<Graphic>();Assert.NotNull(graphic);Assert.That(graphic.GetType().Name,Is.EqualTo("CombatExteriorAperture"));foreach(string layer in new[]{"MapLayer","SelectedRailConsist","ExteriorActors","PursuitRoad"})Assert.NotNull(viewport.Find(layer),layer);Assert.NotNull(g.transform.Find("ApprovedBattle/CabinContent"));}finally{Object.DestroyImmediate(g);}}
 [Test] public void SelectedConsistOwnsNormalExhaustAndWheelDustWithoutDamagingModel(){var d=Driver();var g=View(d);try{var view=g.GetComponent<ApprovedCombatView>();var root=g.transform.Find("ApprovedBattle/ExteriorViewport");Assert.NotNull(root.Find("SelectedRailConsist/Locomotive/NormalExhaust"));Assert.NotNull(root.Find("ConsistWheelDust"));string before=d.StateJson;view.Refresh();Canvas.ForceUpdateCanvases();Assert.AreEqual(before,d.StateJson);g.GetComponentsInChildren<Button>().Single(b=>b.name=="Pause").onClick.Invoke();string paused=d.StateJson;d.Advance(10000000,8);view.Refresh();Assert.AreEqual(paused,d.StateJson);Assert.IsFalse(d.RecoveryRequired);}finally{Object.DestroyImmediate(g);}}
 [Test] public void PursuerHealthKeepsReadableHeightAndActualValue(){var d=Driver();for(int i=0;i<30;i++)d.Advance(1000000,8);var g=View(d);try{var exterior=g.transform.Find("ApprovedBattle/ExteriorViewport/ExteriorActors");var bars=exterior.GetComponentsInChildren<CombatMeter>();Assert.IsNotEmpty(bars);foreach(var bar in bars){float h=bar.rectTransform.rect.height*bar.transform.parent.localScale.y;Assert.GreaterOrEqual(h,6,"screen height must leave room for dark rim and fill");var actor=((Newtonsoft.Json.Linq.JArray)d.HudState["actors"]).Single(a=>(string)a["id"]==bar.transform.parent.name);int hp=(int)actor["hp"],max=(int)actor["maxHp"],shield=(int)actor["shield"];Assert.AreEqual(hp/(float)System.Math.Max(max,hp+shield),bar.Value,.00001f);}string before=d.StateJson;g.GetComponent<ApprovedCombatView>().Refresh();Assert.AreEqual(before,d.StateJson);}finally{Object.DestroyImmediate(g);}}
 [TestCase(1280)][TestCase(1600)] public void ActualRenderHasNoSceneryAtFourOuterFrameCorners(int height){var d=Driver();var g=View(d);var cg=new GameObject("corner-camera",typeof(Camera));var rt=new RenderTexture(720,height,24);var pixels=new Texture2D(720,height,TextureFormat.RGB24,false);var previous=RenderTexture.active;try{var camera=cg.GetComponent<Camera>();camera.targetTexture=rt;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;var c=g.GetComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=1;g.GetComponent<ApprovedCombatView>().Refresh();Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=rt;pixels.ReadPixels(new Rect(0,0,720,height),0,0);pixels.Apply();int offset=(height-1280)/2;foreach(int x in new[]{0,719})foreach(int y in new[]{941,1213}){var color=pixels.GetPixel(x,y+offset);Assert.Less(Mathf.Max(color.r,color.g,color.b),.10f,"scenery leaked at "+x+","+y);}}finally{RenderTexture.active=previous;Object.DestroyImmediate(g);Object.DestroyImmediate(cg);Object.DestroyImmediate(pixels);rt.Release();Object.DestroyImmediate(rt);}}
}
